export function renderEmblemAnimals(
	colors: Partial<EmblemAnimalsColors> = {},
	variant: EmblemVariantId = '04'
): string {
	const c: EmblemAnimalsColors = { ...DEFAULT_EMBLEM_COLORS, ...colors };
	const padColor = c.pad ?? c.paw;
	const animalsPath = EMBLEM_ANIMAL_SILHOUETTES[variant] ?? EMBLEM_PATHS.animals;

	return `
    <!-- 1. Background Circle -->
    <circle cx="${EMBLEM_PATHS.circle.cx}" cy="${EMBLEM_PATHS.circle.cy}" r="${EMBLEM_PATHS.circle.r}" fill="${c.circleBg}" />

    <!-- 2. Paw Pads -->
    <g id="paw-pads" fill="${c.paw}">
      <path id="paw-toe-right" d="${EMBLEM_PATHS.pawToeRight}" />
      <path id="paw-toe-center-right" d="${EMBLEM_PATHS.pawToeCenterRight}" />
      <path id="paw-toe-center-left" d="${EMBLEM_PATHS.pawToeCenterLeft}" />
      <path id="paw-toe-left" d="${EMBLEM_PATHS.pawToeLeft}" />
      <path id="paw-pad" fill="${padColor}" d="${EMBLEM_PATHS.pawPad}" />
    </g>

    <!-- 3. Text VET CREW (Brand Gold) -->
    <path id="text-vet-crew" fill="${c.vetCrew}" d="${EMBLEM_PATHS.textVetCrew}" />

    <!-- 4. Text HOSPITAL (Brand Leaf Green) -->
    <path id="text-hospital" fill="${c.hospital}" d="${EMBLEM_PATHS.textHospital}" />

    <!-- 5. Full Animal Silhouettes Row (Deep Emerald) - Variant ${variant} -->
    <path id="animal-silhouettes" fill="${c.animals}" fill-rule="evenodd" d="${animalsPath}" />

    <!-- 6. Text ЦЕНТР ЛІКУВАННЯ (Deep Emerald) -->
    <path id="text-center-treatment" fill="${c.title}" d="${EMBLEM_PATHS.textTitle}" />

    <!-- 7. Text ЕКЗОТИЧНИХ ТА ДИКИХ ТВАРИН (Leaf Green) -->
    <path id="text-subtitle" fill="${c.subtitle}" d="${EMBLEM_PATHS.textSubtitle}" />
  `.trim();
}
